/**
 * SLATE — what each genre asks of an actor, researched (from 2026-10-10), kept as data in `content/genre-demands.json`
 * (generated by `tools/build-attribute-content.mjs` from `docs/research/attributes/research-genre-demands.json`), and
 * typed here. Until 2026-10-17 the data was the research's own words; from then (brief 14) the builder puts the game's
 * words in what the genre look shows (`docs/research/attributes/genre-demands-words.txt`), and the research file keeps
 * the original. Each claim with its source, what the source actually supports, how it was read, its confidence, the
 * demand tags it supports and what stays uncertain. Only tags of entries at medium or high confidence are applied
 * (`applied` in `content/demands.ts`); a low one's are shown, as not applied, and why.
 */

import type { GenreDemand } from './demands';
import data from './genre-demands.json';

export const GENRE_DEMANDS: Readonly<Record<string, GenreDemand>> = data as Record<string, GenreDemand>;
